readOnlyCommandsForNextAuthorizedStaging.rawOpenInterestRouteProbe:
node --input-type=module <<'EOF'
const to=Date.now(), from=to-4*60*60*1000;
const sets=[
  {name:'binance-only',venues:'binance'},
  {name:'hyperliquid-only',venues:'hyperliquid'},
  {name:'explicit-default',venues:'binance,hyperliquid,bybit'},
  {name:'omitted-venues-default',venues:null}
];
for (const item of sets) {
  const url=new URL('http://127.0.0.1:5173/market-data/v1/raw-open-interest');
  const params=new URLSearchParams({from:String(from),to:String(to),market:'perpetual'});
  if(item.venues!==null) params.set('venues',item.venues);
  url.search=params;
  const response=await fetch(url), body=await response.json();
  const rows=body.observations??[];
  const sample=rows.filter((_,i)=>i<2||i>=rows.length-2).map(row=>({venue:row.venue,nativeSymbol:row.nativeSymbol,sourceTimeMs:row.sourceTimeMs,observedAtMs:row.observedAtMs,epoch:row.epoch,valueDecimal:row.valueDecimal,units:row.units,source:row.source,sourceTimeQuality:row.sourceTimeQuality,quality:row.quality,gapBefore:row.gapBefore}));
  console.log(JSON.stringify({name:item.name,url:url.toString(),status:response.status,returnedVenues:body.venues,from:body.from,to:body.to,truncated:body.truncated,invalidRows:body.invalidRows,observationCount:rows.length,bybitVerification:body.unitVerification?.bybit,bybitFeed:body.feeds?.bybit,bybitObservationCount:rows.filter(row=>row.venue==='bybit').length,sample,error:body.error}));
}
EOF

