readOnlyCommandsForNextAuthorizedStaging.staleStateCheck:
node --input-type=module <<'EOF'
const to=Date.now(), from=to-4*60*60*1000;
const url=new URL('http://127.0.0.1:5173/market-data/v1/raw-open-interest');
url.search=new URLSearchParams({from:String(from),to:String(to),venues:'binance,hyperliquid,bybit',market:'perpetual'});
const response=await fetch(url), body=await response.json();
const feedAges=Object.fromEntries(Object.entries(body.feeds??{}).map(([venue,feed])=>{const ageMs=Number.isSafeInteger(feed.lastObservedAt)?to-feed.lastObservedAt:null;return [venue,{state:feed.state,lastObservedAt:feed.lastObservedAt,ageMs,expectedIntervalMs:feed.expectedIntervalMs,stale:feed.stale,staleByAge:ageMs===null?null:ageMs>75000,unitVerification:feed.unitVerification}]}));
const healthResponse=await fetch('http://127.0.0.1:5173/market-data/v1/health'),health=await healthResponse.json();
console.log(JSON.stringify({rawStatus:response.status,asOfMs:body.asOfMs,feedAges,healthStatus:healthResponse.status,healthOi:health.oi,healthPositioningFeeds:health.netPositioning?.feeds,error:body.error}));
EOF
